#!/usr/bin/env python3
from pathlib import Path
import sys,json,zlib,base64,hashlib
if len(sys.argv)!=2: raise SystemExit("usage: patch-shishalove-1.1.78-index-progress-candidate.py <plugin-dir>")
root=Path(sys.argv[1])
payload=json.loads(zlib.decompress(base64.b64decode("")))
for rel,spec in payload.items():
    p=root/rel; data=p.read_bytes()
    if hashlib.sha256(data).hexdigest()!=spec["sha"]: raise SystemExit("unexpected 1.1.78 baseline: "+rel)
    lines=data.decode("utf-8").splitlines(keepends=True)
    for i1,i2,new in reversed(spec["ops"]): lines[i1:i2]=new.splitlines(keepends=True)
    p.write_text("".join(lines),encoding="utf-8")
php=(root/"shishalove-app-bridge.php").read_text()
for token in ["Version: 1.1.78","skipped_ineligible","last_batch_dirty_attempted","last_batch_sequential_attempted","last_batch_inserted","last_batch_updated","last_batch_already_valid"]:
    if token not in php: raise SystemExit("missing required token: "+token)
if "LIMIT 40" not in php or "vi.product_id IS NULL" not in php: raise SystemExit("eligible-only refill missing")
if "count($due)>=2" not in php or "count($seq)>=6" not in php: raise SystemExit("mixed batch bounds missing")
print("Bridge 1.1.78 visual-index progress candidate patch applied; version intentionally unchanged")
